#pragma once
// Included after the shared curve, step and preset views inside nexumgate.
class PowerHeader:public Button {
public:
 explicit PowerHeader(String name):Button(name){setClickingTogglesState(true);}
 void paintButton(Graphics& g,bool over,bool)override{g.setColour(Colour(over?0xffc4d6df:0xffb6cad5));g.fillRoundedRectangle(getLocalBounds().toFloat(),4);g.fillRect(0,5,getWidth(),getHeight()-5);g.setColour(getToggleState()?yellow():Colour(0xff728792));g.fillEllipse(10,11,6,6);nexumgate::text(g,getButtonText(),{24,0,getWidth()-90,getHeight()},11.5f,getToggleState()?ink():Colour(0xff637784));nexumgate::text(g,getToggleState()?"ON":"BYP",{getWidth()-52,0,42,getHeight()},9,getToggleState()?ink():Colour(0xff637784),Justification::centredRight);}
};
class BareArrow:public Button {
 bool right;
public:
 BareArrow(bool r):Button(r?"Next":"Previous"),right(r){}
 void paintButton(Graphics& g,bool over,bool)override{g.setColour(over?yellow():muted());float x=getWidth()*.5f,y=getHeight()*.5f,sign=right?1.f:-1.f;Path path;path.startNewSubPath(x-sign*1.5f,y-3);path.lineTo(x+sign*1.5f,y);path.lineTo(x-sign*1.5f,y+3);g.strokePath(path,PathStrokeType(1.3f));g.setColour(Colour(0xff344650));g.drawVerticalLine(0,4.f,(float)getHeight()-4);}
};
class QuickShapeIcon:public Button {
 Processor& p;int index;
public:
 QuickShapeIcon(Processor& processor,int shape):Button(shapeNames()[shape]),p(processor),index(shape){setComponentID("shaper-quick:"+String(shape));setTooltip(shapeNames()[shape]);setMouseCursor(MouseCursor::PointingHandCursor);onClick=[this]{p.selectShape(index);repaint();};}
 void paintButton(Graphics& g,bool over,bool)override{bool selected=p.value("custom")<.5f&&(int)p.value("duckShape")==index;g.fillAll(Colour(0xff17242d));if(over){g.setColour(yellow().withAlpha(.06f));g.fillRect(getLocalBounds());}g.setColour(Colour(0xff344650));g.drawVerticalLine(getWidth()-1,0.f,(float)getHeight());g.drawHorizontalLine(getHeight()-1,0.f,(float)getWidth());auto area=getLocalBounds().toFloat().reduced(6,6);Path path;for(int i=0;i<=96;++i){float x=i/96.f,y=area.getBottom()-envelope(x,index)*area.getHeight();if(i==0)path.startNewSubPath(area.getX(),y);else path.lineTo(area.getX()+x*area.getWidth(),y);}g.setColour(selected?yellow():over?yellow().withAlpha(.8f):Colour(0xff728d9c));g.strokePath(path,PathStrokeType(selected?1.8f:1.3f,PathStrokeType::curved,PathStrokeType::rounded));}
};
class ShapeCard:public Component {
 Processor& p;bool pan;PowerHeader power;CurveView curve;ComboBox shape,rate;BareArrow previous{false},next{true};OwnedArray<Knob> knobs;OwnedArray<QuickShapeIcon> quickShapes;TextButton band{"LOW BAND ONLY"};std::unique_ptr<AudioProcessorValueTreeState::ButtonAttachment> powerLink,bandLink;std::unique_ptr<AudioProcessorValueTreeState::ComboBoxAttachment> rateLink;
public:
 ShapeCard(Processor& processor,bool panning):p(processor),pan(panning),power(pan?"PAN":"SHAPER"),curve(p,pan){setComponentID(pan?"pan-card":"shaper-card");for(auto* c:std::initializer_list<Component*>{&power,&curve,&shape,&rate,&previous,&next})addAndMakeVisible(c);shape.addItemList(pan?panNames():shapeNames(),1);shape.onChange=[this]{if(shape.getSelectedId()>0){if(pan)p.set("panShape",(float)shape.getSelectedItemIndex());else p.selectShape(shape.getSelectedItemIndex());}};auto step=[this](int direction){int index=((int)p.value(pan?"panShape":"duckShape")+16+direction)%16;if(pan)p.set("panShape",(float)index);else p.selectShape(index);refresh();};previous.onClick=[step]{step(-1);};next.onClick=[step]{step(1);};rate.addItemList(divisions(),1);rateLink=std::make_unique<AudioProcessorValueTreeState::ComboBoxAttachment>(p.state,pan?"panRate":"duckRate",rate);powerLink=std::make_unique<AudioProcessorValueTreeState::ButtonAttachment>(p.state,pan?"panOn":"duckOn",power);power.getProperties().set("parameterIndex",p.state.getParameter(pan?"panOn":"duckOn")->getParameterIndex());power.setComponentID(pan?"power:pan":"power:shaper");auto add=[&](String id,String name){auto* k=knobs.add(new Knob(p,id,name));addAndMakeVisible(k);};add(pan?"panDepth":"duckDepth","DEPTH");add(pan?"panOffset":"duckOffset","START OFFSET");if(!pan){for(int i=0;i<16;++i){auto* icon=quickShapes.add(new QuickShapeIcon(p,i));addAndMakeVisible(icon);}add("cutoff","BAND FREQUENCY");addAndMakeVisible(band);band.setClickingTogglesState(true);bandLink=std::make_unique<AudioProcessorValueTreeState::ButtonAttachment>(p.state,"band",band);}refresh();}
 void refresh(){shape.setSelectedItemIndex((int)p.value(pan?"panShape":"duckShape"),dontSendNotification);if(!pan&&p.value("custom")>.5f)shape.setText("Custom curve",dontSendNotification);curve.setAlpha(p.value(pan?"panOn":"duckOn")>.5f?1.f:.45f);curve.repaint();power.repaint();for(auto* icon:quickShapes)icon->repaint();for(auto* k:knobs)k->repaint();repaint();}
 void resized()override{int w=getWidth();power.setBounds(0,0,w,28);shape.setBounds(0,28,w-44,24);previous.setBounds(w-44,28,22,24);next.setBounds(w-22,28,22,24);rate.setBounds(48,52,w-48,24);curve.setBounds(0,76,w,226);knobs[0]->setBounds(4,pan?342:406,w/2-8,pan?112:90);knobs[1]->setBounds(w/2+4,pan?342:406,w/2-8,pan?112:90);if(!pan){for(int i=0;i<16;++i){int left=(i%8)*w/8,right=(i%8+1)*w/8;quickShapes[i]->setBounds(left,326+(i/8)*32,right-left,32);}knobs[2]->setBounds(w/4,510,w/2,82);band.setBounds(16,getHeight()-46,w-32,24);}}
 void paint(Graphics& g)override{g.setColour(Colour(0xff17242d));g.fillRoundedRectangle(getLocalBounds().toFloat(),4);g.setColour(Colour(0xff91a6b2));g.fillRoundedRectangle(0,326,(float)getWidth(),(float)getHeight()-326,4);g.fillRect(0,326,getWidth(),5);nexumgate::text(g,"RATE",{7,52,41,24},9,muted());g.setColour(Colour(0xff243442));g.fillRect(0,302,getWidth(),24);float gain=pan?p.panView.load():p.duckView.load();nexumgate::text(g,pan?"STEREO POSITION":"SHAPER GAIN",{10,302,getWidth()-110,24},9,muted());nexumgate::text(g,pan?String(gain*100,0)+" %":String(gain*100,0)+" %",{getWidth()-100,302,90,24},10,yellow(),Justification::centredRight);if(pan){int y=520;g.setColour(ink().withAlpha(.45f));g.drawLine(24,(float)y,getWidth()-24.f,(float)y,1);g.drawVerticalLine(getWidth()/2,y-12.f,y+12.f);g.setColour(yellow());float x=24+(p.panView.load()+1)*.5f*(getWidth()-48);g.fillEllipse(x-5,y-5.f,10,10);nexumgate::text(g,"L",{20,y+18,30,20},10,ink());nexumgate::text(g,"C",{getWidth()/2-15,y+18,30,20},10,ink(),Justification::centred);nexumgate::text(g,"R",{getWidth()-50,y+18,30,20},10,ink(),Justification::centredRight);}nexumgate::text(g,p.value(pan?"panOn":"duckOn")>.5f?"PROCESSING":"BYPASS / SIGNAL THRU",{10,getHeight()-20,getWidth()-20,18},9,ink(),Justification::centred);}
};
class GateCard:public Component {
 Processor& p;PowerHeader power{"GATE"};StepGrid steps;EnvelopeView envelope;ComboBox pattern,rate,length;TextButton actions{"..."};OwnedArray<Knob> knobs;std::unique_ptr<AudioProcessorValueTreeState::ButtonAttachment> powerLink;std::unique_ptr<AudioProcessorValueTreeState::ComboBoxAttachment> patternLink,rateLink,lengthLink;int bound=-1;
public:
 GateCard(Processor& processor):p(processor),steps(p),envelope(p){setComponentID("gate-card");for(auto* c:std::initializer_list<Component*>{&power,&steps,&envelope,&pattern,&rate,&length,&actions})addAndMakeVisible(c);for(int i=0;i<8;++i)pattern.addItem("Pattern "+String(i+1),i+1);for(int i=1;i<=64;++i)length.addItem(String(i)+" steps",i);rate.addItemList(divisions(),1);powerLink=std::make_unique<AudioProcessorValueTreeState::ButtonAttachment>(p.state,"gateOn",power);power.getProperties().set("parameterIndex",p.state.getParameter("gateOn")->getParameterIndex());power.setComponentID("power:gate");patternLink=std::make_unique<AudioProcessorValueTreeState::ComboBoxAttachment>(p.state,"pattern",pattern);actions.onClick=[this]{PopupMenu menu,copy;menu.addItem(1,"Clear pattern");menu.addItem(2,"Fill pattern");int source=(int)p.value("pattern")-1;for(int i=0;i<8;++i)copy.addItem(10+i,"Pattern "+String(i+1),i!=source);menu.addSubMenu("Copy to",copy);auto safe=Component::SafePointer<GateCard>(this);menu.showMenuAsync(PopupMenu::Options().withTargetComponent(&actions),[safe,source](int result){if(!safe)return;if(result>=10&&result<18){safe->p.copyPattern(source,result-10);safe->p.set("pattern",(float)result-9);}else if(result==1||result==2){for(int i=0;i<64;++i){safe->p.set(stepId(source,i),result==2?1.f:0.f);safe->p.set(stepId(source,i,true),0);}}safe->refresh();});};const String ids[]={"attack","decay","sustain","release","gateLength","gateDepth","gateOffset"},names[]={"ATTACK","DECAY","SUSTAIN","RELEASE","LENGTH","DEPTH","OFFSET"};for(int i=0;i<7;++i){auto* k=knobs.add(new Knob(p,ids[i],names[i]));addAndMakeVisible(k);}refresh();}
 void refresh(){int slot=jlimit(0,7,(int)p.value("pattern")-1);if(slot!=bound){bound=slot;rateLink.reset();lengthLink.reset();rateLink=std::make_unique<AudioProcessorValueTreeState::ComboBoxAttachment>(p.state,slotId(slot,"resolution"),rate);lengthLink=std::make_unique<AudioProcessorValueTreeState::ComboBoxAttachment>(p.state,slotId(slot,"length"),length);}steps.setAlpha(p.value("gateOn")>.5f?1.f:.45f);steps.repaint();envelope.repaint();power.repaint();for(auto* k:knobs)k->repaint();repaint();}
 void resized()override{int w=getWidth();power.setBounds(0,0,w,28);pattern.setBounds(0,28,w-32,24);actions.setBounds(w-32,28,32,24);rate.setBounds(0,52,w/2,24);length.setBounds(w/2,52,w-w/2,24);steps.setBounds(0,76,w,226);envelope.setBounds(0,308,w,117);for(int i=0;i<4;++i)knobs[i]->setBounds(i*w/4,442,w/4,90);for(int i=4;i<7;++i)knobs[i]->setBounds((i-4)*w/3,548,w/3,82);}
 void paint(Graphics& g)override{g.setColour(Colour(0xff17242d));g.fillRoundedRectangle(getLocalBounds().toFloat(),4);g.setColour(Colour(0xff91a6b2));g.fillRoundedRectangle(0,432,(float)getWidth(),(float)getHeight()-432,4);g.fillRect(0,432,getWidth(),5);nexumgate::text(g,p.value("gateOn")>.5f?"PROCESSING":"BYPASS / SIGNAL THRU",{10,getHeight()-20,getWidth()-20,18},9,ink(),Justification::centred);}
};
class RackPage:public Component {
 Processor& p;ShapeCard shaper,pan;GateCard gate;ComboBox mode;TargetSlider tempo,threshold;std::unique_ptr<AudioProcessorValueTreeState::ComboBoxAttachment> modeLink;std::unique_ptr<AudioProcessorValueTreeState::SliderAttachment> tempoLink,thresholdLink;
public:
 RackPage(Processor& processor):p(processor),shaper(p,false),pan(p,true),gate(p),tempo(p,"tempo"),threshold(p,"threshold"){setComponentID("gate-rack");for(auto* c:std::initializer_list<Component*>{&shaper,&gate,&pan,&mode,&tempo,&threshold})addAndMakeVisible(c);mode.addItemList({"HOST SYNC","MIDI TRIGGER","AUDIO TRIGGER","FREE RUN"},1);modeLink=std::make_unique<AudioProcessorValueTreeState::ComboBoxAttachment>(p.state,"mode",mode);for(auto* slider:{&tempo,&threshold}){slider->getProperties().set("compactNumeric",true);slider->setColour(Slider::textBoxTextColourId,yellow());slider->setColour(Slider::textBoxBackgroundColourId,Colour(0xff17242d));slider->setColour(Slider::textBoxOutlineColourId,Colour(0xff344650));slider->setSliderStyle(Slider::LinearBar);slider->setTextBoxStyle(Slider::TextBoxLeft,false,130,28);}tempoLink=std::make_unique<AudioProcessorValueTreeState::SliderAttachment>(p.state,"tempo",tempo);thresholdLink=std::make_unique<AudioProcessorValueTreeState::SliderAttachment>(p.state,"threshold",threshold);tempo.textFromValueFunction=[](double v){return String(v,1)+" BPM";};threshold.textFromValueFunction=[](double v){return String(v,1)+" dB";};tempo.valueFromTextFunction=threshold.valueFromTextFunction=[](const String& text){return text.getDoubleValue();};tempo.updateText();threshold.updateText();tempo.setDoubleClickReturnValue(true,120);threshold.setDoubleClickReturnValue(true,-18);}
 void refresh(){shaper.refresh();gate.refresh();pan.refresh();repaint();}
 void resized()override{int w=getWidth(),one=(w-16)/3,h=getHeight()-90;mode.setBounds(0,0,196,28);tempo.setBounds(258,0,128,28);threshold.setBounds(530,0,128,28);shaper.setBounds(0,40,one,h);gate.setBounds(one+8,40,one,h);pan.setBounds(2*(one+8),40,w-2*(one+8),h);}
 void paint(Graphics& g)override{g.fillAll(Colour(0xff12191d));nexumgate::text(g,"TEMPO",{206,0,50,28},9,muted());nexumgate::text(g,"AUDIO THRESHOLD",{398,0,130,28},9,muted());nexumgate::text(g,"SERIAL SIGNAL FLOW",{getWidth()-230,0,230,28},10,yellow(),Justification::centredRight);float y=getHeight()-23.f;int w=getWidth();g.setColour(Colour(0xff344650));g.drawLine(14,y,w-14.f,y,1.5f);const String labels[]={"INPUT",p.value("duckOn")>.5f?"SHAPER":"SHAPER / BYP",p.value("gateOn")>.5f?"GATE":"GATE / BYP",p.value("panOn")>.5f?"PAN":"PAN / BYP","OUTPUT"};for(int i=0;i<5;++i){float x=14+(w-28)*i/4.f;float level=i<4?p.stageMeters[i].load():jmax(p.peaks[0].load(),p.peaks[1].load());g.setColour(level>.0001f?yellow():muted());g.fillEllipse(x-3,y-3,6,6);int left=jlimit(0,w-140,(int)x-70);nexumgate::text(g,labels[i],{left,(int)y-23,140,18},9,level>.0001f?yellow():muted(),Justification::centred);float db=Decibels::gainToDecibels(level,-90.f);nexumgate::text(g,db<=-90?"-inf dB":String(db,1)+" dB",{left,(int)y+7,140,16},9,muted(),Justification::centred);if(i<4){g.setColour(level>.0001f?yellow():muted());g.drawLine(x+4,y,x+(w-28)/4.f-4,y,1.3f);float arrow=x+(w-28)/8.f;g.drawLine(arrow-3,y-3,arrow,y,1.2f);g.drawLine(arrow,y,arrow-3,y+3,1.2f);}}}
};
